function db(): ?PDO {
    static $pdo = false;
    if ($pdo !== false) return $pdo;
    $host = getenv('STAYEASE_DB_HOST') ?: '127.0.0.1';
    $name = getenv('STAYEASE_DB_NAME') ?: 'stayease';
    $user = getenv('STAYEASE_DB_USER') ?: 'root';
    $pass = getenv('STAYEASE_DB_PASSWORD') ?: '';
    try {
        $pdo = new PDO("mysql:host=$host;dbname=$name;charset=utf8mb4", $user, $pass, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);
        $pdo->exec("CREATE TABLE IF NOT EXISTS booking_drafts (draft_id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, homestay_id INT UNSIGNED NOT NULL, check_in DATE NULL, check_out DATE NULL, guests TINYINT UNSIGNED NOT NULL DEFAULT 2, promo_code VARCHAR(30) NULL, special_requests VARCHAR(500) NULL, estimated_total DECIMAL(10,2) NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_drafts_user (user_id), CONSTRAINT fk_drafts_user FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE, CONSTRAINT fk_drafts_homestay FOREIGN KEY (homestay_id) REFERENCES homestays(homestay_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        return $pdo;
    } catch (Throwable $e) { $pdo = null; return null; }
}

function esc($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function go(string $url): never { header('Location: '.$url); exit; }
function flash(string $message, string $type='success'): void { $_SESSION['flash'] = [$message, $type]; }
function current_user(): ?array { return $_SESSION['user'] ?? null; }
function require_login(): void { if (!current_user()) { flash('Sign in to continue.', 'error'); go('?page=login'); } }
function money($v): string { return 'RM '.number_format((float)$v, 0); }

