function stays(): array {
    global $demo; $pdo=db(); if (!$pdo) return $demo;
    try {
        $rows=$pdo->query("SELECT h.*, COALESCE(r.avg_rating, 4.8) rating, COALESCE(r.review_count,0) review_count, (SELECT image_path FROM homestay_images i WHERE i.homestay_id=h.homestay_id ORDER BY i.is_cover DESC,i.sort_order LIMIT 1) image, (SELECT GROUP_CONCAT(t.tag_name SEPARATOR '|') FROM homestay_tags ht JOIN tags t ON t.tag_id=ht.tag_id WHERE ht.homestay_id=h.homestay_id) tag_list FROM homestays h LEFT JOIN v_homestay_ratings r ON r.homestay_id=h.homestay_id WHERE h.status='Active' ORDER BY h.homestay_id")->fetchAll();
        foreach ($rows as &$s) { $s['image'] = !empty($s['image']) && str_starts_with($s['image'],'http') ? $s['image'] : 'https://images.unsplash.com/photo-1602002418082-a4443e081dd1?auto=format&fit=crop&w=1200&q=85'; $s['tags']=!empty($s['tag_list'])?explode('|',$s['tag_list']):[]; unset($s['tag_list']); }
        return $rows ?: $demo;
    } catch(Throwable $e) { return $demo; }
}
function find_stay(int $id): ?array { foreach(stays() as $s) if((int)$s['homestay_id']===$id) return $s; return null; }

