        try {
            if ($action==='create_customer') {
                $name=trim($_POST['full_name']??''); $email=strtolower(trim($_POST['email']??'')); $phone=trim($_POST['phone']??''); $password=$_POST['password']??'';
                if (!$name || !filter_var($email,FILTER_VALIDATE_EMAIL) || !$phone || strlen($password)<8) { flash('Enter a valid name, email and phone number. The temporary password must be at least 8 characters.','error'); go('?page=customer-form'); }
                $q=$pdo->prepare("INSERT INTO users(full_name,email,password_hash,phone,role,status) VALUES(?,?,?,?, 'User','Active')");
                $q->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$phone]);
                flash('Customer account created. Share the temporary password with the customer securely.'); go('?page=customer-detail&id='.(int)$pdo->lastInsertId());
            }
            $id=(int)($_POST['user_id']??0);
            $check=$pdo->prepare("SELECT user_id FROM users WHERE user_id=? AND role='User'"); $check->execute([$id]);
            if (!$check->fetchColumn()) { flash('Customer account not found.','error'); go('?page=customers'); }
            if ($action==='update_customer') {
                $name=trim($_POST['full_name']??''); $email=strtolower(trim($_POST['email']??'')); $phone=trim($_POST['phone']??'');
                if (!$name || !filter_var($email,FILTER_VALIDATE_EMAIL) || !$phone) { flash('Enter a valid name, email and phone number.','error'); go('?page=customer-detail&id='.$id); }
                $q=$pdo->prepare('UPDATE users SET full_name=?,email=?,phone=? WHERE user_id=? AND role=\'User\''); $q->execute([$name,$email,$phone,$id]);
                flash('Customer details updated.'); go('?page=customer-detail&id='.$id);
            }
            $status=($_POST['status']??'')==='Inactive'?'Inactive':'Active';
            $q=$pdo->prepare("UPDATE users SET status=? WHERE user_id=? AND role='User'"); $q->execute([$status,$id]);
            flash($status==='Inactive'?'Customer account deactivated. Existing booking history was kept.':'Customer account reactivated.'); go('?page=customer-detail&id='.$id);
        } catch (PDOException $e) {
            flash($e->getCode()==='23000'?'That email address is already used by another account.':'Could not save the customer account. Please try again.','error');
            go($action==='create_customer'?'?page=customer-form':'?page=customer-detail&id='.(int)($_POST['user_id']??0));
        }
    }
    if ($action==='logout') { $_SESSION=[]; session_destroy(); go('?'); }
    if ($action==='save_draft') {
        require_login(); $stay=find_stay((int)($_POST['homestay_id']??0));
        if (!$stay || !$pdo) { flash('Draft saving needs an available homestay and a connected StayEase database.','error'); go('?page=stays'); }
        $checkin=$_POST['check_in']??''; $checkout=$_POST['check_out']??''; $guests=max(1,min((int)($_POST['guests']??2),(int)$stay['capacity']));
        if ($checkin && $checkout && strtotime($checkout)<=strtotime($checkin)) { flash('Check-out must be after check-in.','error'); go('?page=stay&id='.$stay['homestay_id']); }
        $nights=($checkin&&$checkout)?max(1,(int)((strtotime($checkout)-strtotime($checkin))/86400)):1; $total=$nights*(float)$stay['base_price'];
        $draftId=(int)($_POST['draft_id']??0);
        if($draftId){$q=$pdo->prepare('UPDATE booking_drafts SET homestay_id=?,check_in=?,check_out=?,guests=?,promo_code=?,special_requests=?,estimated_total=? WHERE draft_id=? AND user_id=?');$q->execute([$stay['homestay_id'],$checkin?:null,$checkout?:null,$guests,trim($_POST['promo_code']??'')?:null,trim($_POST['special_requests']??'')?:null,$total,$draftId,current_user()['user_id']]);}
        else {$q=$pdo->prepare('INSERT INTO booking_drafts(user_id,homestay_id,check_in,check_out,guests,promo_code,special_requests,estimated_total) VALUES(?,?,?,?,?,?,?,?)');$q->execute([current_user()['user_id'],$stay['homestay_id'],$checkin?:null,$checkout?:null,$guests,trim($_POST['promo_code']??'')?:null,trim($_POST['special_requests']??'')?:null,$total]);}
        flash('Draft saved. Your dates are not reserved.'); go('?page=bookings&tab=drafts');
    }
    if ($action==='delete_draft') { require_login(); if($pdo){$q=$pdo->prepare('DELETE FROM booking_drafts WHERE draft_id=? AND user_id=?');$q->execute([(int)$_POST['draft_id'],current_user()['user_id']]);} flash('Draft deleted.'); go('?page=bookings&tab=drafts'); }
}

