function stay_card(array $s): string {
    $id=(int)$s['homestay_id']; $img=esc($s['image']); $name=esc($s['name']);
    $place=esc(strtoupper($s['city'].', '.$s['state'])); $rating=esc($s['rating']); $price=money($s['base_price']);
    return '<article class="stay-card"><div class="stay-image" style="background-image:url(\''.$img.'\')"><a class="stay-image-link" href="?page=stay&id='.$id.'" aria-label="View '.$name.'"></a><span class="card-label">CURATED STAY</span><button class="heart" type="button" data-stay-id="'.$id.'" aria-label="Add '.$name.' to saved stays" aria-pressed="false">♡</button></div><div class="stay-card-body"><div class="stay-card-meta"><span>'.$place.'</span><b>★ '.$rating.'</b></div><a href="?page=stay&id='.$id.'"><h3>'.$name.'</h3></a><div class="stay-card-bottom"><span>'.$price.' <small>/ night</small></span><a href="?page=stay&id='.$id.'">View stay ↗</a></div></div></article>';
}
